<template>
  <view v-if="product" class="page"><scroll-view scroll-y class="scroll"><swiper class="gallery" :current="current" @change="current = $event.detail.current"><swiper-item v-for="(image,index) in images" :key="image"><image :src="image" mode="aspectFill" @tap="preview(index)"/></swiper-item></swiper><view class="counter">{{ current + 1 }}/{{ images.length }}</view><view class="info"><view><text class="ui-strong">{{ product.points_price }}</text><text> 积分</text><text v-if="Number(product.cash_price)>0"> + ¥{{ product.cash_price }}</text></view><view class="level-note">兑换等级：{{ minMemberLevelName }}及以上 <text v-if="!canRedeem">当前等级不足</text></view><text class="title">{{ product.name }}</text><text class="desc">{{ product.desc }}</text></view><view class="block" @tap="openSku"><text>已选</text><text>{{ selectedColor || selectedSpec || '默认规格' }}</text><text>›</text></view><view class="block params"><text class="block-title">主要参数</text><view v-for="item in params" :key="item.key"><text>{{ item.label }}</text><text>{{ item.value }}</text></view></view><view v-if="detailImages.length" class="detail"><text class="block-title">详情展示</text><image v-for="image in detailImages" :key="image" :src="image" mode="widthFix"/></view><view class="safe-space"/></scroll-view><view class="bottom"><view class="mini" @tap="home">首页</view><button class="mini" open-type="contact" :session-from="'points_' + product.id">客服</button><button class="mini" open-type="share">分享</button><button class="redeem" :class="{ disabled: !canRedeem }" @tap="openSku">{{ canRedeem ? '立即兑换' : '会员等级不足' }}</button></view><view v-if="skuVisible" class="mask" @tap="closeSku"><view class="panel" @tap.stop><view class="sku-head"><image :src="product.cover_image || images[0] || '/static/navigation/sravx-mark.png'" mode="aspectFill"/><view><text class="ui-strong">{{ selectedOption.pointsText }} 积分</text><text v-if="Number(selectedOption.cashText)>0">+ ¥{{ selectedOption.cashText }}</text><text class="ui-small">已选：{{ pendingColor || selectedColor || '请选择商品规格' }}</text><view class="stepper"><button :disabled="pendingQuantity<=1" @tap="pendingQuantity--">−</button><text>{{ pendingQuantity }}</text><button @tap="pendingQuantity++">＋</button></view></view><text @tap="closeSku">×</text></view><text class="sku-title">商品规格</text><view v-for="option in colorOptions" :key="option.name" class="option" :class="{ selected: pendingColor === option.name }" @tap="pendingColor=option.name"><image :src="option.image" mode="aspectFill"/><text>{{ option.name }}</text><text>{{ option.pointsText }} 积分</text></view><button class="redeem confirm" @tap="confirmSku">立即兑换</button></view></view></view>
  <view v-else-if="loading" class="state">加载中...</view><view v-else class="state">积分商品不存在</view>
</template>
<script>
import api from '../../common/api.js'
import auth from '../../common/auth.js'
const parseImages = raw => { if (Array.isArray(raw)) return raw.filter(Boolean); if (typeof raw === 'string') { try { const result = JSON.parse(raw); return Array.isArray(result) ? result.filter(Boolean) : raw ? [raw] : [] } catch (error) { return raw ? [raw] : [] } } return [] }
export default { data() { return { product: null, loading: true, current: 0, images: [], selectedSpec: null, colorOptions: [], selectedColor: '', pendingColor: '', pendingQuantity: 1, skuVisible: false, canRedeem: true, minMemberLevelName: 'LV1', detailImages: [], params: [] } }, computed: { selectedOption() { return this.colorOptions.find(item => item.name === (this.pendingColor || this.selectedColor)) || this.colorOptions[0] || { pointsText: this.product && this.product.points_price || 0, cashText: this.product && this.product.cash_price || 0 } } }, onLoad(options) { if (options.id) this.load(options.id); else this.loading = false }, methods: { async load(id) { try { const product = await api.getPointsProductDetail(Number(id)); if (!product) return; const images = parseImages(product.images); this.product = product; this.images = images.length ? images : [product.cover_image || '/static/navigation/sravx-mark.png']; this.selectedSpec = Array.isArray(product.specs) && product.specs[0] ? typeof product.specs[0] === 'string' ? product.specs[0] : product.specs[0].name || '默认规格' : '默认规格'; const main = { name: product.short_name || product.name || '默认规格', image: product.cover_image || this.images[0], pointsText: String(Number(product.points_price) || 0), cashText: String(Number(product.cash_price) || 0) }; this.colorOptions = [main].concat((product.specs || []).filter(item => item && typeof item === 'object' && item.name && item.name !== main.name).map(item => ({ name: item.name, image: item.option_images || main.image, pointsText: String(item.points_price != null ? item.points_price : main.pointsText), cashText: String(item.cash_price != null ? item.cash_price : main.cashText) }))); this.selectedColor = main.name; this.canRedeem = product.can_redeem !== false; this.minMemberLevelName = product.min_member_level_name || 'LV1'; this.detailImages = parseImages(product.detail_images); this.params = [{ key: 'core', label: '核心材质', value: product.core_material || '--' }, { key: 'handle', label: '手柄材质', value: product.handle_material || '--' }, { key: 'size', label: '尺寸', value: product.size || '--' }, { key: 'weight', label: '重量', value: product.weight || '--' }, { key: 'warranty', label: '保修期', value: product.warranty_period || '--' }] } catch (error) { uni.showToast({ title: '加载失败', icon: 'none' }) } finally { this.loading = false } }, preview(index) { uni.previewImage({ current: this.images[index], urls: this.images }) }, home() { uni.reLaunch({ url: '/pages/index/index' }) }, openSku() { if (!this.canRedeem) return uni.showToast({ title: `需${this.minMemberLevelName}可兑换`, icon: 'none' }); this.pendingColor = this.selectedColor; this.pendingQuantity = 1; this.skuVisible = true }, closeSku() { this.skuVisible = false }, confirmSku() { const user = auth.user(); if (!user || !user.phone) return uni.navigateTo({ url: '/pages/register/index' }); const option = this.selectedOption; this.selectedColor = this.pendingColor || this.selectedColor; this.skuVisible = false; const data = encodeURIComponent(JSON.stringify({ id: this.product.id, name: this.product.name, desc: this.product.desc, price: option.pointsText, cashPrice: Number(option.cashText) || 0, supportMixedPay: Number(this.product.support_mixed_pay) === 1, cover_image: option.image, selectedColor: option.name, spec: this.selectedSpec || '默认规格', quantity: this.pendingQuantity })); uni.navigateTo({ url: `/pages/confirm-order/index?productData=${data}&isPointsOrder=true` }) } } }
</script>
<style>
.page,.scroll{height:100vh;background:#F4F6F8}.gallery{height:330px;background:#fff}.gallery image{width:100%;height:100%}.counter{position:absolute;right:12px;top:300px;padding:3px 7px;border-radius:12px;background:rgba(0,0,0,.5);color:#fff;font-size:11px}.info,.block,.detail{padding:16px;background:#fff}.info .ui-strong{color:#0B0D10;font-size:26px}.info>div:first-child text{color:#0B0D10;font-size:13px}.level-note{margin-top:7px;color:#0B0D10;font-size:11px}.level-note text{color:#4A4A4D}.title,.desc{display:block}.title{margin-top:9px;font-size:17px;font-weight:650}.desc{margin-top:5px;color:#636366;font-size:13px}.block{display:flex;justify-content:space-between;margin-top:8px;font-size:14px}.params,.detail{display:block}.block-title{display:block;margin-bottom:12px;font-size:15px;font-weight:650}.params view{display:flex;justify-content:space-between;padding:7px 0;border-top:1px solid #f1f1f1;font-size:13px}.params view text:first-child{color:#636366}.detail{margin-top:8px}.detail image{display:block;width:100%}.safe-space{height:85px}.bottom{position:fixed;bottom:0;left:0;right:0;display:flex;align-items:center;padding:8px 10px calc(8px + env(safe-area-inset-bottom));background:#fff}.mini{margin:0;padding:0 7px;background:transparent;color:#636366;font-size:11px;line-height:36px}.mini::after,.redeem::after{border:0}.redeem{flex:1;margin-left:8px;border-radius:21px;background:linear-gradient(90deg,#69727E,#69727E);color:#fff;font-size:14px;line-height:42px}.redeem.disabled{background:#c7c7cc}.mask{position:fixed;inset:0;z-index:9;display:flex;align-items:flex-end;background:rgba(0,0,0,.4)}.panel{width:100%;max-height:80vh;padding:15px;box-sizing:border-box;border-radius:14px 14px 0 0;background:#fff}.sku-head{display:flex;gap:10px}.sku-head>image{width:72px;height:72px;border-radius:7px}.sku-head>view{flex:1}.sku-head .ui-strong,.sku-head .ui-small,.sku-head text{display:block}.sku-head .ui-strong,.sku-head text{color:#0B0D10}.sku-head .ui-small{margin-top:4px;color:#636366;font-size:11px}.stepper{display:flex;align-items:center;gap:8px;margin-top:7px}.stepper button{width:25px;height:25px;margin:0;padding:0;line-height:23px}.sku-title{display:block;margin:14px 0 7px;font-size:14px;font-weight:650}.option{display:flex;align-items:center;gap:9px;margin-bottom:7px;padding:7px;border:1px solid #eee;border-radius:7px;font-size:12px}.option.selected{border-color:#0B0D10;background:#F7F8FA}.option image{width:34px;height:34px;border-radius:4px}.option text:last-child{margin-left:auto;color:#0B0D10}.confirm{width:100%;margin:10px 0 0}.state{padding:100px 0;text-align:center;color:#636366}
</style>
